parameters.jsCode:
// RSS থেকে পাওয়া প্রতিটি খবরকে পোর্টালের API এর ফরম্যাটে সাজানো হচ্ছে
const j = $input.item.json;
const html = j['content:encoded'] || j.content || j.contentSnippet || j.summary || '';

// ছবি: আগে enclosure, না থাকলে লেখার প্রথম <img>
let image = (j.enclosure && j.enclosure.url) || '';
if (!image) {
  const m = /<img[^>]+src=["']([^"']+)["']/i.exec(html);
  if (m) image = m[1];
}

return {
  json: {
    title: String(j.title || '').trim(),
    content: html || String(j.title || ''),
    link: j.link || '',
    image,
    category: 'news',            // এখানে আপনার ক্যাটেগরির slug দিন (যেমন: sports, economy)
    tags: Array.isArray(j.categories) ? j.categories : [],
  },
};

